		// message and throws std::runtime_error. Both are cdecl, one FMOD_RESULT argument (add esp, 4 at every call).
		void logFmodResult(FMOD_RESULT result);   // 005b87a0
		void checkFmodResult(FMOD_RESULT result); // 005b6fe0

