		for (size_t i = 0; i < numChildren(); ++i)
		{
			const GuiItem* item = dynamic_cast<const GuiItem*>(getChild(i));
			if (item)
			{
				if (item == child)
					return position;
				position += childOffset();
			}
		}
		return position;
	}

